    if eff > ctx.value("max_effort"):
        return {"value": eff, "detail": "finger_joint effort exceeded clamp limit for u_brown"}
    return None

def check(ctx):
    held = ctx.held_object()
    if held != "u_brown":
        return None
    t = ctx.transform("tcp", "u_brown")
    pos = t["translation"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = pos
        return None
    ref = ctx.state["ref"]
    d = ctx.dist(pos, ref)
    if d > ctx.value("slip_tol"):
        return {"value": d, "detail": "u_brown moved relative to gripper while held"}
    return None

